class XmlParser {
    constructor() {
        this.findInObj = (obj, chave) => {
            if (obj.hasOwnProperty(chave)) {
                return obj[chave];
            }
            for (let prop in obj) {
                if (typeof obj[prop] === 'object') {
                    const result = this.findInObj(obj[prop], chave); // Passar a chave aqui
                    if (result) {
                        return result;
                    }
                }
            }
            return '';
        };
    }
    removeJsonTextAttribute(value, parentElement) {
        const pOpKeys = Object.keys(parentElement._parent);
        const keyNo = pOpKeys.length;
        const keyName = pOpKeys[keyNo - 1];
        const arrOfKey = parentElement._parent[keyName];
        const arrOfKeyLen = arrOfKey.length;
        if (arrOfKeyLen > 0) {
            const arr = arrOfKey;
            const arrIndex = arrOfKey.length - 1;
            arr[arrIndex] = value;
        }
        else {
            parentElement._parent[keyName] = value;
        }
    }
    getStatusServicoBody(jsonData) {
        return this.findInObj(jsonData, 'retConsStatServ');
    }
    getConsultaProtocoloBody(jsonData) {
        return this.findInObj(jsonData, 'retConsSitNFe');
    }
    getConsultaCadastroBody(jsonData) {
        return this.findInObj(jsonData, 'retConsCad');
    }
    getRecepcaoEventoBody(jsonData) {
        return this.findInObj(jsonData, 'retEnvEvento');
    }
    getDistribuicaoDFe(jsonData) {
        // Tenta encontrar resposta NFe primeiro
        let result = this.findInObj(jsonData, 'nfeDistDFeInteresseResult');
        // Se não encontrar, tenta resposta CTe
        if (!result) {
            result = this.findInObj(jsonData, 'cteDistDFeInteresseResult');
        }
        return result;
    }
    getDistribuicaoDFeProcBody(jsonData) {
        return this.findInObj(jsonData, 'NFe');
    }
    getDistribuicaoDFeResBody(jsonData) {
        // Tenta encontrar resNFe primeiro, senão tenta resCTe
        let result = this.findInObj(jsonData, 'resNFe');
        if (!result) {
            result = this.findInObj(jsonData, 'resCTe');
        }
        return result;
    }
    getDistribuicaoDFeEventBody(jsonData) {
        return this.findInObj(jsonData, 'evento');
    }
    getAutorizacaoEventBody(jsonData) {
        return this.findInObj(jsonData, 'retEnviNFe');
    }
    getAutorizacaoFinalEventBody(jsonData) {
        return this.findInObj(jsonData, 'nfeProc');
    }
    getAutorizacaoRetornoEventBody(jsonData) {
        return this.findInObj(jsonData, 'protNFe');
    }
    getInutilizacaoRetornoEventBody(jsonData) {
        return this.findInObj(jsonData, 'infInut');
    }
    getNFSeAutorizacaoBody(jsonData) {
        return this.findInObj(jsonData, 'NFSe') || this.findInObj(jsonData, 'infNFSe') || jsonData;
    }
    convertXmlToJson(xml, metodo, nsu) {
        logger.info(`Convertendo XML para JSON [${metodo}]`, {
            context: 'XmlParser',
        });
        const jsonAsString = convert.xml2json(xml, {
            compact: true,
            spaces: 2,
            ignoreAttributes: true,
            ignoreDeclaration: true,
            trim: true,
            ignoreInstruction: true,
            ignoreComment: true,
            ignoreCdata: true,
            ignoreDoctype: true,
            textFn: this.removeJsonTextAttribute,
        });
        const jsonData = JSON.parse(jsonAsString);
        let jsonBody;
        switch (metodo) {
            case 'NFEStatusServico':
                jsonBody = this.getStatusServicoBody(jsonData);
                break;
            case 'NFEConsultaProtocolo':
                jsonBody = this.getConsultaProtocoloBody(jsonData);
                break;
            case 'NfeConsultaCadastro':
                jsonBody = this.getConsultaCadastroBody(jsonData);
                break;
            case 'RecepcaoEvento':
                jsonBody = this.getRecepcaoEventoBody(jsonData);
                break;
            case 'NFeDistribuicaoDFe':
                jsonBody = this.getDistribuicaoDFe(jsonData);
                break;
            case 'CTeDistribuicaoDFe':
                jsonBody = this.getDistribuicaoDFe(jsonData);
                break;
            case 'NFeDistribuicaoDFe_proc':
                jsonBody = jsonData;
                break;
            case 'NFeDistribuicaoDFe_res':
                jsonBody = this.getDistribuicaoDFeResBody(jsonData);
                break;
            case 'NFeDistribuicaoDFe_event':
                jsonBody = this.getDistribuicaoDFeEventBody(jsonData);
                break;
            case 'CTeDistribuicaoDFe_proc':
                jsonBody = jsonData;
                break;
            case 'CTeDistribuicaoDFe_res':
                jsonBody = this.getDistribuicaoDFeResBody(jsonData);
                break;
            case 'CTeDistribuicaoDFe_event':
                jsonBody = this.getDistribuicaoDFeEventBody(jsonData);
                break;
            case 'NFEAutorizacao':
                jsonBody = this.getAutorizacaoEventBody(jsonData);
                break;
            case 'NFEAutorizacaoFinal':
                jsonBody = this.getAutorizacaoFinalEventBody(jsonData);
                break;
            case 'NFCEAutorizacaoFinal':
                jsonBody = this.getAutorizacaoFinalEventBody(jsonData);
                break;
            case 'NFERetAutorizacao':
                jsonBody = this.getAutorizacaoRetornoEventBody(jsonData);
                break;
            case 'NFEInutilizacao':
                jsonBody = this.getInutilizacaoRetornoEventBody(jsonData);
                break;
            case 'NFSeAutorizacao':
            case 'NFSEAutorizacao':
                jsonBody = this.getNFSeAutorizacaoBody(jsonData);
                break;
            default:
                throw new Error('Formato de XML desconhecido');
        }
        if (jsonBody) {
            if (nsu) {
                jsonBody.nsu = nsu;
            }
            jsonBody.xml = xml;
        }
        return jsonBody;
    }
    /**
     * Converte um XML de envio (`enviNFe`) ou uma `NFe` solo em uma
     * estrutura JSON compatível com o tipo `NFe` esperado pelos serviços
     * de Autorização de NFe/NFCe (`{ idLote, indSinc, NFe }`).
     *
     * Formatos aceitos:
     *  - Envelope `enviNFe` contendo uma ou mais `NFe`.
     *  - `nfeProc` (XML autorizado) — extrai a `NFe` interna.
     *  - `NFe` solo — empacota com defaults (`idLote=1`, `indSinc=1`).
     *
     * Defaults são aplicáveis somente para os campos do envelope; o
     * conteúdo de `infNFe` não é alterado e segue o fluxo normal de
     * geração/assinatura no service.
     *
     * @param xml String XML de entrada.
     * @param overrides Permite sobrescrever `idLote`/`indSinc` quando o XML
     *                  não contém envelope.
     */
    convertXmlEnvioNFeToJson(xml, overrides) {
        logger.info('Convertendo XML de envio para JSON', {
            context: 'XmlParser',
            method: 'convertXmlEnvioNFeToJson',
        });
        const jsonData = this.parseNfeLikeXml(xml);
        let envelope = this.findInObj(jsonData, 'enviNFe');
        if (!envelope) {
            const nfeProc = this.findInObj(jsonData, 'nfeProc');
            const nfeNode = nfeProc ? this.findInObj(nfeProc, 'NFe') : this.findInObj(jsonData, 'NFe');
            if (!nfeNode) {
                throw new Error('XML inválido: não foi possível localizar `enviNFe` ou `NFe`.');
            }
            envelope = {
                idLote: overrides?.idLote ?? '1',
                indSinc: overrides?.indSinc ?? 1,
                NFe: nfeNode,
            };
        }
        // Normaliza CNPJ/CPF -> CNPJCPF nas NFe (formato esperado pela lib)
        const nfeList = Array.isArray(envelope.NFe) ? envelope.NFe : [envelope.NFe];
        nfeList.forEach((n) => this.normalizeNfeForLibFormat(n));
        return {
            idLote: envelope.idLote ?? overrides?.idLote ?? '1',
            indSinc: Number(envelope.indSinc ?? overrides?.indSinc ?? 1),
            NFe: envelope.NFe,
        };
    }
    /**
     * Converte um XML autorizado (`nfeProc`) ou uma `NFe` solo em uma
     * estrutura JSON compatível com o gerador de DANFE
     * (`{ NFe, protNFe? }`), além de retornar a chave de acesso quando
     * disponível.
     *
     * @param xml String XML de entrada.
     */
    convertXmlNfeProcToJson(xml) {
        logger.info('Convertendo nfeProc para JSON', {
            context: 'XmlParser',
            method: 'convertXmlNfeProcToJson',
        });
        const jsonData = this.parseNfeLikeXml(xml);
        const nfeProc = this.findInObj(jsonData, 'nfeProc');
        const NFe = nfeProc ? this.findInObj(nfeProc, 'NFe') : this.findInObj(jsonData, 'NFe');
        if (!NFe) {
            throw new Error('XML inválido: não foi possível localizar `NFe` ou `nfeProc`.');
        }
        const protNFe = nfeProc ? this.findInObj(nfeProc, 'protNFe') : this.findInObj(jsonData, 'protNFe');
        const chFromProt = protNFe?.infProt?.chNFe;
        const idAttr = NFe?.infNFe?.Id ?? '';
        const chFromId = typeof idAttr === 'string' ? idAttr.replace(/^NFe/, '') : '';
        const chave = chFromProt || chFromId || '';
        const data = { NFe };
        if (protNFe)
            data.protNFe = protNFe;
        return { data, chave };
    }
    /**
     * Converte um XML de NFSe (padrão nacional — nó `NFSe`/`infNFSe`) em uma
     * estrutura JSON compatível com o gerador de DANFSe, além de retornar a
     * chave de acesso quando disponível (atributo `Id` do nó `infNFSe`).
     *
     * Formatos aceitos:
     *  - `NFSe` completa (retorno da autorização/consulta/distribuição).
     *  - `infNFSe` solo.
     *
     * @param xml String XML de entrada.
     */
    convertXmlNFSeToJson(xml) {
        logger.info('Convertendo NFSe para JSON', {
            context: 'XmlParser',
            method: 'convertXmlNFSeToJson',
        });
        const jsonData = this.parseNfeLikeXml(xml);
        const NFSe = this.findInObj(jsonData, 'NFSe');
        const infNFSe = NFSe ? this.findInObj(NFSe, 'infNFSe') : this.findInObj(jsonData, 'infNFSe');
        if (!infNFSe || typeof infNFSe !== 'object' || Array.isArray(infNFSe)) {
            throw new Error('XML inválido: não foi possível localizar `NFSe` ou `infNFSe`.');
        }
        // A chave de acesso da NFSe é o atributo `Id` prefixado com "NFS".
        const idAttr = typeof infNFSe.Id === 'string' ? infNFSe.Id : '';
        if (!idAttr) {
            throw new Error('XML inválido: `infNFSe` não possui o atributo `Id` (chave de acesso).');
        }
        const chave = idAttr.replace(/^NFS/, '');
        return { data: { infNFSe }, chave };
    }
    /**
     * Converte um XML autorizado (`cteProc`) ou um `CTe` solo em uma
     * estrutura JSON compatível com o gerador de DACTE
     * (`{ CTe, protCTe? }`), além de retornar a chave de acesso quando
     * disponível.
     *
     * @param xml String XML de entrada.
     */
    convertXmlCteProcToJson(xml) {
        logger.info('Convertendo cteProc para JSON', {
            context: 'XmlParser',
            method: 'convertXmlCteProcToJson',
        });
        const jsonData = this.parseNfeLikeXml(xml);
        const cteProc = this.findInObj(jsonData, 'cteProc');
        const CTe = cteProc ? this.findInObj(cteProc, 'CTe') : this.findInObj(jsonData, 'CTe');
        if (!CTe) {
            throw new Error('XML inválido: não foi possível localizar `CTe` ou `cteProc`.');
        }
        const protCTe = cteProc ? this.findInObj(cteProc, 'protCTe') : this.findInObj(jsonData, 'protCTe');
        const chFromProt = protCTe?.infProt?.chCTe;
        const idAttr = CTe?.infCte?.Id ?? '';
        const chFromId = typeof idAttr === 'string' ? idAttr.replace(/^CTe/, '') : '';
        const chave = chFromProt || chFromId || '';
        const data = { CTe };
        if (protCTe)
            data.protCTe = protCTe;
        return { data, chave };
    }
    /**
     * Faz o parse de um XML de NFe/NFCe (envio, retorno ou solo) preservando
     * atributos e elevando-os para o nível do elemento (ex.: `Id` em `infNFe`,
     * `versao` em `NFe`, `nItem` em `det`). Necessário para alimentar o
     * fluxo interno da lib que espera atributos como propriedades comuns.
     */
    parseNfeLikeXml(xml) {
        const jsonAsString = convert.xml2json(xml, {
            compact: true,
            spaces: 2,
            ignoreAttributes: false,
            ignoreDeclaration: true,
            trim: true,
            ignoreInstruction: true,
            ignoreComment: true,
            ignoreCdata: true,
            ignoreDoctype: true,
            textFn: this.removeJsonTextAttribute,
        });
        const parsed = JSON.parse(jsonAsString);
        this.liftAttributes(parsed);
        return parsed;
    }
    /**
     * Eleva, recursivamente, as chaves de `_attributes` para o próprio nível
     * do elemento e remove o nó `_attributes`. Compatível com a saída de
     * `xml-js` em modo compacto.
     */
    liftAttributes(node) {
        if (!node || typeof node !== 'object')
            return;
        if (Array.isArray(node)) {
            node.forEach(item => this.liftAttributes(item));
            return;
        }
        if (node._attributes && typeof node._attributes === 'object') {
            for (const attrKey of Object.keys(node._attributes)) {
                if (!(attrKey in node)) {
                    node[attrKey] = node._attributes[attrKey];
                }
            }
            delete node._attributes;
        }
        for (const key of Object.keys(node)) {
            const value = node[key];
            if (value && typeof value === 'object') {
                this.liftAttributes(value);
            }
        }
    }
    /**
     * Normaliza uma `NFe` parseada de XML para o formato interno da lib:
     *  - converte `CNPJ`/`CPF`/`idEstrangeiro` em `CNPJCPF` em `emit`,
     *    `dest`, `transp.transporta` e `NFref.refNFP`.
     *  - remove atributos elevados que a lib re-aplica via `$` ao montar
     *    o XML final (`infNFe.versao`, `det.nItem`), evitando duplicidade
     *    no XML gerado.
     *
     * Observação: `infRespTec` mantém o campo `CNPJ` original — a lib não
     * unifica documento para esse nó.
     */
    normalizeNfeForLibFormat(nfeNode) {
        const infNFe = nfeNode?.infNFe;
        if (!infNFe || typeof infNFe !== 'object')
            return;
        // versao é re-aplicado pela lib via $ ao montar `infNFe`
        delete infNFe.versao;
        // O atributo `Id` no XML vem com prefixo "NFe" (ex.: "NFe4126..."),
        // mas a lib espera apenas a chave de 44 dígitos em `infNFe.Id` —
        // ela própria re-prefixa com "NFe" ao calcular `chaveAcesso`.
        if (typeof infNFe.Id === 'string' && /^NFe\d{44}$/.test(infNFe.Id)) {
            infNFe.Id = infNFe.Id.slice(3);
        }
        this.unifyDocFields(infNFe.emit);
        this.unifyDocFields(infNFe.dest);
        this.unifyDocFields(infNFe.transp?.transporta);
        // nItem é re-aplicado pela lib via $ em cada `det` quando é array.
        // Por isso normalizamos sempre para array (no XML, com 1 item, viraria
        // objeto único e a lib não re-aplicaria nItem, quebrando a validação XSD).
        const det = infNFe.det;
        if (Array.isArray(det)) {
            det.forEach((d) => { if (d && typeof d === 'object')
                delete d.nItem; });
        }
        else if (det && typeof det === 'object') {
            delete det.nItem;
            infNFe.det = [det];
        }
        const NFref = infNFe.NFref;
        if (Array.isArray(NFref)) {
            NFref.forEach((ref) => this.unifyDocFields(ref?.refNFP));
        }
        else if (NFref && typeof NFref === 'object') {
            this.unifyDocFields(NFref.refNFP);
        }
    }
    /**
     * Em um nó (ex.: `emit`, `dest`), unifica `CNPJ`/`CPF`/`idEstrangeiro`
     * em um único campo `CNPJCPF`, removendo as chaves originais. Mantém a
     * primeira não-vazia encontrada na ordem `CNPJ → CPF → idEstrangeiro`.
     */
    unifyDocFields(target) {
        if (!target || typeof target !== 'object')
            return;
        if (target.CNPJCPF)
            return;
        const candidate = target.CNPJ || target.CPF || target.idEstrangeiro;
        if (candidate) {
            target.CNPJCPF = candidate;
        }
        delete target.CNPJ;
        delete target.CPF;
        delete target.idEstrangeiro;
    }
}

class BaseNFE {
    constructor(environment, utility, xmlBuilder, metodo, axios, saveFiles, gerarConsulta) {
        this.environment = environment;
        this.utility = utility;
        this.xmlBuilder = xmlBuilder;
        this.metodo = metodo;
        this.axios = axios;
        this.saveFiles = saveFiles;
        this.gerarConsulta = gerarConsulta;
        this.chaveNfe = "";
        this.modelo = 'NFe';
    }
    /**
     * Método de geração do XML - Deve ser implementado pelas subclasses
     */
    gerarXml(data) {
        throw new Error("O método 'gerarXml' não foi implementado na subclasse.");
    }
    setContentType() {
        const UF = this.environment.config.dfe.UF;
        const ufsAppSoad = ['MG', 'GO', 'MT', 'MS', 'AM', 'DF'];
        if (ufsAppSoad.includes(UF)) {
            return 'application/soap+xml';
        }
        return 'text/xml; charset=utf-8';
    }
    buildHeaders(ContentType, action) {
        const headers = {
            'Content-Type': ContentType,
        };
        if (!action) {
            return headers;
        }
        if (/soap\+xml/i.test(ContentType)) {
            headers['Content-Type'] = ContentType.replace(/\s*;\s*action="[^"]*"/i, '') + `; action="${action}"`;
            return headers;
        }
        headers.SOAPAction = `"${action}"`;
        return headers;
    }
    async callWebService(xmlConsulta, webServiceUrl, ContentType, action, agent) {
        const startTime = Date.now();
        const headers = this.buildHeaders(ContentType, action);
        logger.http('Iniciando comunicação com o webservice', {
            context: `BaseNFE`,
            method: this.metodo,
            url: webServiceUrl,
            action,
            headers,
        });
        const response = await this.axios.post(webServiceUrl, xmlConsulta, {
            headers,
            httpsAgent: agent
        });
        const duration = Date.now() - startTime;
        logger.http('Comunicação concluída com sucesso', {
            context: `BaseNFE`,
            method: this.metodo,
            duration: `${duration}ms`,
            responseSize: response.data ? JSON.stringify(response.data).length : 0
        });
        return response;
    }
    /**
     * Método para obter o modelo
     */
    getModelo(data) {
        return this.modelo || 'NFe';
    }
    /**
     * Executa a requisição ao webservice SEFAZ
     * @param {any} [data] - Dados opcionais usados para gerar o XML em algumas subclasses.
     * @returns {Promise<any>} A resposta do webservice em JSON.
     */
    async Exec(data) {
        let xmlConsulta = '';
        let xmlConsultaSoap = '';
        let webServiceUrlTmp = '';
        let responseInJson = undefined;
        let xmlRetorno = {};
        const ContentType = this.setContentType();
        try {
            // Gerando XML específico
            xmlConsulta = this.gerarXml(data);
            const modelo = this.getModelo(data);
            const { xmlFormated, agent, webServiceUrl, action } = await this.gerarConsulta.gerarConsulta(xmlConsulta, this.metodo, undefined, undefined, modelo);
            xmlConsultaSoap = xmlFormated;
            webServiceUrlTmp = webServiceUrl;
            const xmlRetorno = await this.callWebService(xmlFormated, webServiceUrl, ContentType, action, agent);
            // Instanciando classe de utilitários com lib xml-js e convertendo XML para XmlParser
            const json = new XmlParser();
            responseInJson = json.convertXmlToJson(xmlRetorno.data, this.metodo);
            // Gera erro em caso de Rejeição
            if (responseInJson.xMotivo.includes('Rejeição')) {
                throw new Error(responseInJson.xMotivo);
            }
            return responseInJson;
        }
        finally {
            this.saveFiles.salvaArquivos(xmlConsulta, responseInJson, xmlRetorno, this.metodo, xmlConsultaSoap);
        }
    }
}

class BaseNFSe {
    constructor(environment, utility, xmlBuilder, metodo, axios, saveFiles, gerarConsulta) {
        this.environment = environment;
        this.utility = utility;
        this.xmlBuilder = xmlBuilder;
        this.metodo = metodo;
        this.axios = axios;
        this.saveFiles = saveFiles;
        this.gerarConsulta = gerarConsulta;
    }
    /**
     * Método de preparação dos dados - Deve ser implementado pelas subclasses
     */
    prepararDados(_data) {
        throw new Error("O método 'prepararDados' não foi implementado na subclasse.");
    }
    /**
     * Texto que será salvo como XML de consulta.
     * Subclasses podem sobrescrever para persistir o artefato realmente enviado.
     */
    getXmlConsulta(requestData) {
        return requestData ? JSON.stringify(requestData, null, 2) : '';
    }
    getCodigoRetornoParaLog(responseData) {
        if (!responseData || typeof responseData !== 'object') {
            return undefined;
        }
        if (responseData.cStat !== undefined) {
            return responseData.cStat;
        }
        if (responseData.codigoRetorno !== undefined) {
            return responseData.codigoRetorno;
        }
        const erros = responseData.erros || responseData.Erros;
        if (Array.isArray(erros) && erros.length > 0) {
            return erros[0]?.Codigo || erros[0]?.codigo;
        }
        return responseData.Codigo || responseData.codigo;
    }
    getMensagemRetornoParaLog(responseData) {
        if (!responseData || typeof responseData !== 'object') {
            return undefined;
        }
        if (responseData.mensagemRetorno) {
            return responseData.mensagemRetorno;
        }
        if (responseData.xMotivo) {
            return responseData.xMotivo;
        }
        if (responseData.message) {
            return responseData.message;
        }
        if (responseData.Descricao) {
            return responseData.Descricao;
        }
        if (responseData.descricao) {
            return responseData.descricao;
        }
        const erros = responseData.erros || responseData.Erros;
        if (Array.isArray(erros) && erros.length > 0) {
            return erros[0]?.Descricao || erros[0]?.descricao;
        }
        const alertas = responseData.alertas || responseData.Alertas;
        if (Array.isArray(alertas) && alertas.length > 0) {
            return alertas[0]?.Descricao || alertas[0]?.descricao || alertas[0]?.message;
        }
        if (responseData.chaveAcesso) {
            return 'Autorizado';
        }
        return undefined;
    }
    getComplementoRetornoParaLog(responseData) {
        if (!responseData || typeof responseData !== 'object') {
            return undefined;
        }
        if (responseData.complementoRetorno) {
            return responseData.complementoRetorno;
        }
        if (responseData.complemento) {
            return responseData.complemento;
        }
        if (responseData.Complemento) {
            return responseData.Complemento;
        }
        const erros = responseData.erros || responseData.Erros;
        if (Array.isArray(erros) && erros.length > 0) {
            return erros[0]?.complemento || erros[0]?.Complemento;
        }
        const alertas = responseData.alertas || responseData.Alertas;
        if (Array.isArray(alertas) && alertas.length > 0) {
            return alertas[0]?.complemento || alertas[0]?.Complemento;
        }
        return undefined;
    }
    getPrimeiroErroRetorno(responseData) {
        if (!responseData || typeof responseData !== 'object') {
            return undefined;
        }
        const erros = responseData.erros || responseData.Erros;
        if (Array.isArray(erros) && erros.length > 0) {
            return erros[0];
        }
        const alertas = responseData.alertas || responseData.Alertas;
        if (Array.isArray(alertas) && alertas.length > 0) {
            return alertas[0];
        }
        if (responseData.codigo !== undefined ||
            responseData.Codigo !== undefined ||
            responseData.descricao !== undefined ||
            responseData.Descricao !== undefined) {
            return responseData;
        }
        return undefined;
    }
    extrairErroDetalhado(responseData, statusHttp) {
        const primeiroErro = this.getPrimeiroErroRetorno(responseData);
        if (!primeiroErro) {
            return undefined;
        }
        const codigo = primeiroErro.codigo || primeiroErro.Codigo;
        const descricao = primeiroErro.descricao ||
            primeiroErro.Descricao ||
            primeiroErro.mensagem ||
            primeiroErro.message;
        const complemento = primeiroErro.complemento || primeiroErro.Complemento;
        return {
            codigo,
            descricao,
            complemento,
            statusHttp,
            raw: primeiroErro,
        };
    }
    createNFSeError(message, detail) {
        const error = new Error(message);
        if (detail) {
            error.nfseErrorDetail = detail;
        }
        return error;
    }
    normalizarRetornoParaLog(responseData, httpStatus) {
        if (!responseData || typeof responseData !== 'object') {
            return responseData;
        }
        const retornoNormalizado = { ...responseData };
        const erros = retornoNormalizado.erros || retornoNormalizado.Erros;
        const possuiErros = Array.isArray(erros) && erros.length > 0;
        const codigoRetorno = this.getCodigoRetornoParaLog(retornoNormalizado);
        const mensagemRetorno = this.getMensagemRetornoParaLog(retornoNormalizado);
        const complementoRetorno = this.getComplementoRetornoParaLog(retornoNormalizado);
        if (httpStatus !== undefined) {
            retornoNormalizado.statusHttp = httpStatus;
        }
        if (retornoNormalizado.sucesso === undefined) {
            retornoNormalizado.sucesso = !possuiErros && (httpStatus === undefined || httpStatus < 400);
        }
        if (codigoRetorno !== undefined && retornoNormalizado.codigoRetorno === undefined) {
            retornoNormalizado.codigoRetorno = codigoRetorno;
        }
        if (mensagemRetorno && retornoNormalizado.mensagemRetorno === undefined) {
            retornoNormalizado.mensagemRetorno = mensagemRetorno;
        }
        if (complementoRetorno && retornoNormalizado.complementoRetorno === undefined) {
            retornoNormalizado.complementoRetorno = complementoRetorno;
        }
        return retornoNormalizado;
    }
    getXmlRetornoParaSalvar(errorResponse, response) {
        const xmlRetornoParaSalvar = errorResponse || response;
        if (xmlRetornoParaSalvar && xmlRetornoParaSalvar.data) {
            return {
                ...xmlRetornoParaSalvar,
                data: this.normalizarRetornoParaLog(xmlRetornoParaSalvar.data, xmlRetornoParaSalvar.status || response?.status),
            };
        }
        return {
            ...(response || {}),
            data: this.normalizarRetornoParaLog({
                sucesso: false,
                metodo: this.metodo,
                mensagem: errorResponse?.message || 'Resposta vazia do webservice NFSe',
                dataHora: new Date().toISOString(),
            }, response?.status),
        };
    }
    /**
     * Método para obter a URL base do webservice
     */
    getWebServiceUrl() {
        return this.utility.getWebServiceUrlNFSe(this.metodo);
    }
    /**
     * Método para obter o método HTTP (GET, POST, etc)
     */
    getHttpMethod() {
        return 'POST'; // Padrão para NFSe
    }
    /**
     * Método para obter o path adicional da URL (ex: /nfse/{chaveAcesso})
     */
    getUrlPath(_data) {
        return '';
    }
    /**
     * Método para obter query parameters
     */
    getQueryParams(_data) {
        return {};
    }
    /**
     * Executa a requisição ao webservice NFSe (REST API)
     * @param {any} [data] - Dados opcionais usados para preparar a requisição.
     * @returns {Promise<any>} A resposta do webservice em JSON.
     */
    async Exec(data) {
        let requestData = null;
        let webServiceUrl = '';
        let responseInJson = undefined;
        let response = {};
        let errorResponse = null;
        try {
            // Prepara dados específicos
            requestData = this.prepararDados(data);
            // Obtém URL base
            const baseUrl = this.getWebServiceUrl();
            const path = this.getUrlPath(data);
            const queryParams = this.getQueryParams(data);
            // Monta URL completa
            webServiceUrl = baseUrl + path;
            if (Object.keys(queryParams).length > 0) {
                const queryString = new URLSearchParams(queryParams).toString();
                webServiceUrl += `?${queryString}`;
            }
            const httpMethod = this.getHttpMethod();
            logger.http('Iniciando comunicação com o webservice NFSe', {
                context: `BaseNFSe`,
                method: this.metodo,
                httpMethod,
                url: webServiceUrl,
            });
            // Executa requisição REST
            // Obtém o agent HTTPS do environment para garantir autenticação mútua TLS
            const agent = this.environment.getHttpAgent();
            const requestConfig = {
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                },
                // Garante que o httpsAgent seja usado explicitamente para autenticação mútua TLS
                httpsAgent: agent
            };
            if (httpMethod === 'GET') {
                response = await this.axios.get(webServiceUrl, requestConfig);
            }
            else if (httpMethod === 'POST') {
                response = await this.axios.post(webServiceUrl, requestData, requestConfig);
            }
            else if (httpMethod === 'PUT') {
                response = await this.axios.put(webServiceUrl, requestData, requestConfig);
            }
            else if (httpMethod === 'DELETE') {
                response = await this.axios.delete(webServiceUrl, requestConfig);
            }
            logger.http('Comunicação concluída com sucesso', {
                context: `BaseNFSe`,
                method: this.metodo,
                responseSize: response.data ? JSON.stringify(response.data).length : 0
            });
            // NFSe retorna JSON diretamente
            responseInJson = response.data;
            // Verifica se há erros na resposta
            if (responseInJson) {
                const detalheErroRetorno = this.extrairErroDetalhado(responseInJson, response?.status);
                if (detalheErroRetorno) {
                    const mensagemErro = detalheErroRetorno.codigo
                        ? `${detalheErroRetorno.codigo}: ${detalheErroRetorno.descricao || 'Erro desconhecido'}`
                        : detalheErroRetorno.descricao || 'Erro desconhecido';
                    throw this.createNFSeError(mensagemErro, detalheErroRetorno);
                }
            }
            return responseInJson || {};
        }
        catch (error) {
            // Armazena a resposta de erro para uso no finally
            errorResponse = error.response;
            // Tenta extrair mais informações do erro
            let errorMessage = error.message || 'Erro desconhecido';
            if (error.response) {
                // Erro de resposta HTTP
                // Tenta extrair mensagem do body da resposta
                if (error.response.data) {
                    if (typeof error.response.data === 'string') {
                        errorMessage = `HTTP ${error.response.status}: ${error.response.data}`;
                    }
                    else {
                        const detalheErro = this.extrairErroDetalhado(error.response.data, error.response.status);
                        if (detalheErro) {
                            errorMessage = detalheErro.codigo
                                ? `${detalheErro.codigo}: ${detalheErro.descricao || 'Erro desconhecido'}`
                                : detalheErro.descricao || 'Erro desconhecido';
                            error.nfseErrorDetail = detalheErro;
                        }
                        if (!detalheErro && error.response.data.message) {
                            errorMessage = error.response.data.message;
                        }
                        else if (!detalheErro && error.response.data.descricao) {
                            errorMessage = error.response.data.descricao;
                        }
                        else if (!detalheErro && error.response.data.Descricao) {
                            errorMessage = error.response.data.Descricao;
                        }
                        else if (!detalheErro) {
                            errorMessage = `HTTP ${error.response.status}: ${JSON.stringify(error.response.data)}`;
                        }
                    }
                }
                else {
                    errorMessage = `HTTP ${error.response.status}: ${error.response.statusText}`;
                }
            }
            logger.error(``, error, {
                context: `BaseNFSe][${this.metodo}`
            });
            if (error?.nfseErrorDetail) {
                throw error;
            }
            throw this.createNFSeError(errorMessage, {
                statusHttp: error?.response?.status,
                raw: error?.response?.data,
            });
        }
        finally {
            // Salva arquivos (se configurado)
            const xmlConsulta = this.getXmlConsulta(requestData);
            const xmlRetornoParaSalvar = this.getXmlRetornoParaSalvar(errorResponse, response);
            this.saveFiles.salvaArquivos(xmlConsulta, responseInJson, xmlRetornoParaSalvar, this.metodo, '' // xmlConsultaSoap vazio para REST
            );
        }
    }
}

